/**
 * Files the latest due occurrence of every active recurring-issue rule as an ordinary issue, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): createIssue, assertNotArchived, can
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

const DAY_MS = 86_400_000;

/** Runs are serialized so two overlapping passes cannot file the same occurrence twice. */
let lastRun: Promise<unknown> = Promise.resolve();

export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  const run = lastRun.then(() => sweep(now));
  lastRun = run.catch(() => undefined);
  return run;
}

function sweep(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listActiveRules();

    for (const rule of rules) {
      try {
        if (await fileOccurrence(rule, now)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** Returns true when an issue was created. */
async function fileOccurrence(rule: RecurringIssue, now: Date): Promise<boolean> {
