/**
 * Creates a rule after the gates a hand-made issue would face — tenant scope,
 * a live project, `issue:create` — plus an active assignee and the plan's
 * rule quota (paused rules count).
 */
export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
