  assertOrgScope(actor, rule.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (rule.assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
    if (assignee === null || assignee.status !== "active") {
      throw new Error(`User ${rule.assigneeId} is not an active member`);
    }
  }

  const org = requireFound(
    await orgRepo.findOrgById(rule.orgId),
    "Organization",
    rule.orgId,
  );
  const cap = getPlanLimits(org.plan).recurringIssues;

  const created = await recurringRepo.insertRecurringIssueWithinCap(
    { ...rule, createdBy: actor.userId },
    cap,
  );
  if (created === null) {
    throw new Error(
